// A kind of coin.
// Ref: #/components/schemas/Coin
type Coin string

const (
	CoinCp Coin = "cp"
	CoinSp Coin = "sp"
	CoinEp Coin = "ep"
	CoinGp Coin = "gp"
	CoinPp Coin = "pp"
)

// AllValues returns all Coin values.
func (Coin) AllValues() []Coin {
	return []Coin{
		CoinCp,
		CoinSp,
		CoinEp,
		CoinGp,
		CoinPp,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s Coin) MarshalText() ([]byte, error) {
	switch s {
	case CoinCp:
		return []byte(s), nil
	case CoinSp:
		return []byte(s), nil
	case CoinEp:
		return []byte(s), nil
	case CoinGp:
		return []byte(s), nil
	case CoinPp:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *Coin) UnmarshalText(data []byte) error {
	switch Coin(data) {
	case CoinCp:
		*s = CoinCp
		return nil
	case CoinSp:
		*s = CoinSp
		return nil
	case CoinEp:
		*s = CoinEp
		return nil
	case CoinGp:
		*s = CoinGp
		return nil
	case CoinPp:
		*s = CoinPp
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

