type LiveUpdateKind string

const (
	LiveUpdateKindSnapshot      LiveUpdateKind = "snapshot"
	LiveUpdateKindView          LiveUpdateKind = "view"
	LiveUpdateKindRejected      LiveUpdateKind = "rejected"
	LiveUpdateKindEnded         LiveUpdateKind = "ended"
	LiveUpdateKindPath          LiveUpdateKind = "path"
	LiveUpdateKindAttackPreview LiveUpdateKind = "attack_preview"
	LiveUpdateKindAreaPreview   LiveUpdateKind = "area_preview"
	LiveUpdateKindPing          LiveUpdateKind = "ping"
	LiveUpdateKindRoll          LiveUpdateKind = "roll"
	LiveUpdateKindRegroup       LiveUpdateKind = "regroup"
	LiveUpdateKindRouteMeasured LiveUpdateKind = "route_measured"
)

// AllValues returns all LiveUpdateKind values.
func (LiveUpdateKind) AllValues() []LiveUpdateKind {
	return []LiveUpdateKind{
		LiveUpdateKindSnapshot,
		LiveUpdateKindView,
		LiveUpdateKindRejected,
		LiveUpdateKindEnded,
		LiveUpdateKindPath,
		LiveUpdateKindAttackPreview,
		LiveUpdateKindAreaPreview,
		LiveUpdateKindPing,
		LiveUpdateKindRoll,
		LiveUpdateKindRegroup,
		LiveUpdateKindRouteMeasured,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s LiveUpdateKind) MarshalText() ([]byte, error) {
	switch s {
	case LiveUpdateKindSnapshot:
		return []byte(s), nil
	case LiveUpdateKindView:
		return []byte(s), nil
	case LiveUpdateKindRejected:
		return []byte(s), nil
	case LiveUpdateKindEnded:
		return []byte(s), nil
	case LiveUpdateKindPath:
		return []byte(s), nil
	case LiveUpdateKindAttackPreview:
		return []byte(s), nil
	case LiveUpdateKindAreaPreview:
		return []byte(s), nil
	case LiveUpdateKindPing:
		return []byte(s), nil
	case LiveUpdateKindRoll:
		return []byte(s), nil
	case LiveUpdateKindRegroup:
		return []byte(s), nil
	case LiveUpdateKindRouteMeasured:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *LiveUpdateKind) UnmarshalText(data []byte) error {
	switch LiveUpdateKind(data) {
	case LiveUpdateKindSnapshot:
		*s = LiveUpdateKindSnapshot
		return nil
	case LiveUpdateKindView:
		*s = LiveUpdateKindView
		return nil
	case LiveUpdateKindRejected:
		*s = LiveUpdateKindRejected
		return nil
	case LiveUpdateKindEnded:
		*s = LiveUpdateKindEnded
		return nil
	case LiveUpdateKindPath:
		*s = LiveUpdateKindPath
		return nil
	case LiveUpdateKindAttackPreview:
		*s = LiveUpdateKindAttackPreview
		return nil
	case LiveUpdateKindAreaPreview:
		*s = LiveUpdateKindAreaPreview
		return nil
	case LiveUpdateKindPing:
		*s = LiveUpdateKindPing
		return nil
	case LiveUpdateKindRoll:
		*s = LiveUpdateKindRoll
		return nil
	case LiveUpdateKindRegroup:
		*s = LiveUpdateKindRegroup
		return nil
	case LiveUpdateKindRouteMeasured:
		*s = LiveUpdateKindRouteMeasured
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

// LiveUpdateNoContent is response for LiveUpdate operation.
type LiveUpdateNoContent struct{}

// What one audience may see now. With fog, a hex is visible now, remembered, or in neither list
// because the party never saw it; nothing in it is sent. Walls, lights and ambient go to the DM only.
// Ref: #/components/schemas/LiveView
type LiveView struct {
	Tokens     []LiveToken   `json:"tokens"`
	Map        OptLiveMap    `json:"map"`
	Fog        bool          `json:"fog"`
	Visible    []HexCoord    `json:"visible"`
	Remembered []HexCoord    `json:"remembered"`
	Combat     OptLiveCombat `json:"combat"`
	Manual     []LiveManual  `json:"manual"`
	// The DM is resolving part of an Effect by hand.
	Resolving OptBool         `json:"resolving"`
	Saves     []LiveSave      `json:"saves"`
	Surfaces  []LiveSurface   `json:"surfaces"`
	Elevation []LiveElevation `json:"elevation"`
	Area      OptLiveArea     `json:"area"`
	Table     OptLiveTable    `json:"table"`
	World     OptLiveWorld    `json:"world"`
	// The party sneaking with a group Stealth check; Reach is where the creatures the audience sees would
	// notice it.
	Sneak OptLiveViewSneak `json:"sneak"`
	// Exploration in turns, outside a fight.
	Exploration OptLiveViewExploration `json:"exploration"`
	// The Surface catalogue, for the DM's paint tool.
	SurfaceKinds []LiveViewSurfaceKindsItem `json:"surfaceKinds"`
	// The shared roster strip as this audience may see it, the fight in initiative order or every creature
	// it can see.
	Roster []LiveRosterEntry `json:"roster"`
	// The Campaign's homebrew conditions, for the DM's effect picker.
	Conditions []LiveViewConditionsItem `json:"conditions"`
	// The Map Objects the audience knows; the party never gets secret ones or ones outside what it has
	// seen.
	Objects    []LiveObject     `json:"objects"`
	Zones      []LiveZone       `json:"zones"`
	Perception []LivePerception `json:"perception"`
	Checks     []LiveCheck      `json:"checks"`
	Inventory  []LiveContainer  `json:"inventory"`
	Shop       OptLiveShop      `json:"shop"`
	Rest       OptLiveRest      `json:"rest"`
	// The day on the Campaign's Game Clock. Rests, travel and the DM move the clock on.
	GameDay OptInt32 `json:"gameDay"`
	// The time of day on the Game Clock, in minutes after midnight. Dawn is at 360; charges that come back
	// at dawn do so when the clock passes it.
	GameMinute OptInt32 `json:"gameMinute"`
	// Every Character of the Campaign, those with a place in the Marching Order first, from the front. Of
	// two of the party equally near, an enemy goes for the one further to the front.
	MarchingOrder []LiveMarcher `json:"marchingOrder"`
	// The points the DM can rewind to, oldest first. Sent to the DM only.
	Checkpoints []LiveCheckpoint `json:"checkpoints"`
	// The Campaign is played without undo. Sent to the DM only.
	NoUndo OptBool `json:"noUndo"`
	// The Sessions a split party plays in. Sent to the DM only, and only while the party is split.
	Groups  []LiveGroup     `json:"groups"`
	Walls   []HexCoord      `json:"walls"`
	Lights  []LiveLight     `json:"lights"`
	Ambient OptAmbientLight `json:"ambient"`
}

